"건강검진 결과지의 붉은 글씨를 의사가 볼펜 끝으로 하나씩 천천히 짚으며 고개를 저었다":"Bác sĩ dùng đầu bút bi chỉ từng chỗ chữ đỏ trên phiếu kết quả khám sức khỏe rồi lắc đầu",
