"검진 결과지에 빨간 글씨가 늘어난 걸 보고, 대수롭지 않은 척하는 나 대신 {0}이/가 재검사 날짜를 먼저 잡았다":"Thấy chữ đỏ trên phiếu kết quả nhiều thêm, mình làm như không có gì, còn {0} đã đặt ngày khám lại trước mình",
"검진 결과지에 빨간 글씨가 늘어난 걸 보고, 재검사 날짜를 달력에 큼직한 동그라미로 쳐 두었다":"Thấy chữ đỏ trên phiếu kết quả nhiều thêm, mình khoanh một vòng tròn to lên ngày khám lại trên tờ lịch",
