"검진표에 빨간 글씨가 늘었지만 병원비가 걱정돼, 아무에게도 보이지 않고 서랍 맨 아래에 넣어 두었다":"Chữ đỏ trên phiếu khám nhiều thêm nhưng lo viện phí, mình không cho ai xem mà cất xuống đáy ngăn kéo",
