"손주를 무릎에 앉히고, 어릴 적 할머니가 들려주던 옛이야기를 목소리까지 흉내 내 한 편 통째로 들려줬다":"Để cháu ngồi lên đùi, kể trọn một câu chuyện cổ bà ngày xưa hay kể, còn bắt chước cả giọng bà",
"송별회에서 받은 꽃다발을 안고 버스로 퇴근하며, 내일부터는 아침 알람을 맞추지 않아도 된다는 게 낯설었다":"Ôm bó hoa nhận ở tiệc chia tay, đi xe buýt về, thấy lạ lẫm vì từ mai không cần đặt báo thức buổi sáng nữa",
