"수업을 빼먹고 혼자 담을 넘어 오락실과 간식 가게를 쏘다니다 해 질 녘에야 슬금슬금 집으로 돌아왔다":"Trốn học một mình trèo tường, lang thang quanh quán game và hàng ăn vặt đến chiều tà mới rón rén về nhà",
"수입이 들쭉날쭉했다":"Thu nhập lúc được lúc không",
"수학여행 버스 맨 뒷자리에서 마이크를 돌려 가며 반 전체가 목이 쉬도록 노래했다":"Ở hàng ghế cuối xe buýt chuyến tham quan, cả lớp chuyền micro nhau hát đến khản cả giọng",
"수화기 너머로 {0}의 헛기침이 한참 이어졌다. 괜찮다는 말뿐이었다":"Bên kia đầu dây, {0} húng hắng ho khan mãi. Chỉ nói được là không sao",
"수확 잔치 날 북소리에 맞춰 마을 어른과 아이 모두가 먼지 이는 마당에서 어울려 춤을 췄다":"Ngày hội mùa gặt, theo tiếng trống, người lớn trẻ nhỏ trong làng cùng nhảy múa giữa sân bụi mù",
"수확 잔치 마당에서 북소리에 맞춰 어른들과 어깨를 맞대고 발을 굴러 흙먼지를 일으키며 밤이 깊어 가는 줄 몰랐다":"Trên sân hội mùa gặt, vai kề vai với người lớn, theo tiếng trống giậm chân cho bụi đất tung lên, chẳng biết đêm đã khuya",
"숙제를 안 해 온 탓에 교실 앞에 서서 선생님의 긴 훈계를 고개 숙이고 끝까지 들었다":"Vì không làm bài tập, đứng trước lớp cúi đầu nghe cô giáo răn dạy một hồi dài đến hết",
"숙취로 아침 알람을 세 번이나 끄고서야 겨우 눈을 뜨는 날이 한 주에 두세 번씩 늘었다":"Những ngày phải tắt báo thức buổi sáng ba lần mới mở nổi mắt vì còn say rượu đêm trước tăng lên, mỗi tuần hai ba lần",
"숟가락을 놓는다":"Đặt thìa xuống",
"술래잡기에서 담벼락 뒤에 바싹 붙어 숨소리를 죽인 채 해가 질 때까지 끝내 안 잡혔고 술래가 포기하고 나서야 터져 나오는 웃음을 참지 못했다":"Chơi trốn tìm, nép sát sau bức tường nín thở, đến khi mặt trời lặn vẫn không bị bắt, đợi người tìm bỏ cuộc mới không nhịn được bật cười",
"술자리 초대를 하나씩 정중하게 거절하고 그날부터 밤 열한 시면 일찍 불을 껐다":"Lịch sự từ chối từng lời mời đi nhậu, từ hôm đó mười một giờ đêm là tắt đèn sớm",
"술자리는 한 주에 한 번만 나가기로 하고 달력에 작은 동그라미를 쳐 두었다":"Quyết định mỗi tuần chỉ đi nhậu một lần, rồi khoanh một vòng tròn nhỏ trên tờ lịch",
"숨이 차올라 뛰던 길을 이제는 천천히 걸었고, 예전엔 지나치기만 하던 가로수의 이름을 알게 됐다":"Con đường từng chạy đến hụt hơi giờ thong thả đi bộ, và biết được tên những hàng cây ven đường mà trước đây chỉ lướt qua",
"쉬고 싶어도 쉴 수가 없다":"Muốn nghỉ mà không nghỉ được",
"쉬는 날 도서관 구석 자리에서 영상 편집 책을 펴 놓고, 낯선 화면의 메뉴를 한 줄씩 따라 눌러 보았다":"Ngày nghỉ, ngồi góc thư viện mở sách chỉnh sửa video, bấm theo từng dòng menu của màn hình lạ",
"쉬는 날 도서관 구석 자리에서 오래 미뤄 둔 책을 펴, 문 닫는 안내 방송이 나올 때까지 읽었다":"Ngày nghỉ, ngồi góc thư viện mở cuốn sách hoãn đọc từ lâu, đọc cho đến khi có thông báo đóng cửa",
"쉬는 날 이웃 어른에게 용접 기술을 배워, 부러져 헛간에 처박혀 있던 낡은 쟁기를 직접 고쳤다":"Ngày nghỉ, học nghề hàn từ một bác hàng xóm, tự tay sửa cái cày cũ gãy bị vứt xó trong kho",
"쉬는 날을 지킨다":"Giữ ngày nghỉ",
"쉬는 시간마다 건물 뒤편에 모이는 무리 틈에서, 얻어 문 담배가 어느새 내 것이 되었다":"Giữa nhóm tụ tập sau tòa nhà mỗi giờ giải lao, điếu thuốc xin hút lúc nào chẳng hay đã thành của mình",
"쉬는 시간에 교무실로 갔다. 선생님이 고개를 끄덕이며 메모를 남겼다":"Giờ ra chơi đi đến phòng giáo viên. Cô giáo gật đầu và ghi lại vài dòng",
"쉬어 간다":"Nghỉ một chút",
"쉬어 보니 시간이 남는다":"Nghỉ rồi mới thấy thời gian còn dư",
"쉬지 않고 쏟아진 비에 강둑이 터져, 한 해 정성껏 키운 밭이 허리 높이 흙탕물 아래 잠겨 버렸다":"Mưa trút không ngớt làm vỡ bờ sông, thửa ruộng chăm sóc cả năm chìm dưới làn nước bùn ngang lưng",
"스리랑카":"Sri Lanka",
