"시에라리온":"Sierra Leone",
"시장 골목에서 갓 튀긴 간식을 종이에 받아 길가에 서서 호호 불어 먹으며, 오늘 하루의 피로를 덜어 냈다":"Trong ngõ chợ, nhận món ăn vặt vừa rán xong trong tờ giấy, đứng bên đường thổi phù phù mà ăn, xua bớt mệt nhọc của một ngày",
"시장 골목에서 옛 짝꿍이 먼저 알아보고 손을 흔든다":"Trong ngõ chợ, bạn ngồi cùng bàn ngày xưa nhận ra mình trước và vẫy tay",
"시험 시간, 옆자리 답안지가 훤히 보인다":"Giờ thi, bài của người bên cạnh hiện rõ mồn một",
"시험 전날 밤 {0}이/가 등잔 곁에 쪼그려 앉아 내 공책을 읽지도 못하면서 말없이 한 장 한 장 소중히 넘겨 보았다":"Đêm trước kỳ thi, {0} ngồi xổm bên đèn dầu, dù không đọc được vẫn lặng lẽ lật từng trang vở của mình một cách trân trọng",
