"시험 전날 밤, {0}의 방 앞에 따뜻한 우유를 놓고 문틈의 불빛만 한참 바라보았다":"Đêm trước kỳ thi, đặt ly sữa ấm trước cửa phòng {0}, rồi chỉ nhìn ánh đèn qua khe cửa thật lâu",
"시험을 망친 성적표를 {0}에게 보여야 한다":"Phải đưa {0} xem bảng điểm thi hỏng",
