"식구 몇이서 손수레에 이불과 솥을 싣고, 이웃 마을에 얻은 새 집으로 이사를 갔다, 마당 큰 나무가 마음에 들었다":"Mấy người trong nhà chất chăn và nồi lên xe kéo tay, chuyển sang căn nhà mới thuê được ở làng bên, thích cây to ngoài sân",
"식구가 하나둘 도시로 떠난 집에서 밥상을 혼자 차려, 반찬 두 가지로 저녁을 때웠다":"Trong căn nhà người thân lần lượt lên thành phố, một mình dọn mâm cơm, tối nay qua loa với hai món ăn kèm",
"식구들 건강":"Sức khỏe của người nhà",
"식구들과 몇 해에 걸쳐 갚았다":"Cùng gia đình trả dần qua vài năm",
"식구들과 짐을 싸서 {0}에 건너가 {1} 일부터 시작했다":"Cùng gia đình gói đồ sang {0}, bắt đầu từ công việc {1}",
"식구와 같이 떠난다":"Đi cùng gia đình",
"식당 메뉴판 글씨가 번져 팔을 쭉 뻗고 읽다가, 며칠 뒤 못 이기는 척 안경점에서 돋보기를 맞췄다":"Chữ trên thực đơn nhà hàng nhòe đi, duỗi thẳng tay ra đọc, mấy hôm sau miễn cưỡng ra tiệm mắt kính chọn kính lão",
"식당 메뉴판 글씨가 번져 팔을 쭉 뻗고 읽던 나를 보고, {0}이/가 웃으며 길 건너 안경점을 가리켰다":"Thấy mình duỗi tay đọc thực đơn vì chữ nhòe, {0} cười và chỉ sang tiệm mắt kính bên kia đường",
"신발 밑창이 떨어져 나가 자갈길을 맨발로 걷는 내내 발끝에 힘을 주고 걸음을 아꼈다":"Đế giày bong ra, đi chân trần trên đường sỏi, suốt quãng đường cứ dồn lực vào đầu ngón chân và tiết kiệm từng bước",
"신발이 젖지 않게 손에 들고 시냇물을 건너 십 리 학교 길을 혼자서 해 뜨기 전에 걸었다":"Xách giày trên tay cho khỏi ướt, lội qua suối, một mình đi con đường mười ri đến trường trước khi mặt trời mọc",
"신분증 주소를 따라 한참을 걸어 돌려주었다. 주인이 두 손으로 내 손을 감쌌다":"Theo địa chỉ trên thẻ căn cước đi bộ một quãng dài để trả lại. Chủ thẻ nắm lấy tay mình bằng cả hai tay",
"신생아 질환":"Bệnh sơ sinh",
"신입이 같은 실수를 세 번째 하던 날, 올라오는 화를 삼키고 처음부터 화면을 같이 보며 설명해 주었다":"Hôm người mới lặp lại lỗi cũ lần thứ ba, nuốt cơn giận đang dâng lên, cùng xem màn hình giảng lại từ đầu",
"신입이 회의 때마다 구석에서 놀림받는 걸 보고, 점심시간에 일부러 곁에 앉아 이름을 또박또박 불러 주었다":"Thấy người mới bị trêu ở góc phòng mỗi buổi họp, giờ nghỉ trưa cố ý ngồi cạnh và gọi rõ tên bạn ấy",
"실랑이 끝에 장난감이 내 품에 남았다. 이긴 기분은 오래가지 않았다":"Sau một hồi giằng co, món đồ chơi còn lại trong lòng mình. Cảm giác thắng chẳng kéo dài",
"실험실에서 알코올램프 불꽃 색이 바뀌는 걸 숨죽이고 지켜보았다":"Nín thở dõi theo màu ngọn lửa đèn cồn đổi thay trong phòng thí nghiệm",
"심부름 가던 길에 동전을 잃어버려 주머니를 뒤집다 {0}에게 눈물을 글썽이며 이실직고했다":"Trên đường đi chạy việc làm mất đồng xu, lộn túi ra tìm rồi rưng rưng nước mắt thú nhận với {0}",
"심장병":"Bệnh tim",
