"웃고 넘긴다":"Cười xòa cho qua",
"웃음이 잦아들 때까지 버텼더니 어느새 그 말씨를 흉내 내는 아이가 늘었다":"Gắng chịu đến khi tiếng cười lắng xuống, chẳng mấy chốc đã có thêm nhiều đứa bắt chước giọng nói đó",
