"웅덩이를 첨벙이며 뛰었다. 홀딱 젖고도 웃음이 그치지 않았다":"Chạy lõm bõm qua các vũng nước. Ướt như chuột lột mà tiếng cười vẫn không dứt",
"월급 대부분을 집으로 보냈다":"Đã gửi phần lớn tiền lương về nhà",
"월급 명세서 숫자가 조금 늘어, 퇴근길에 {0}에게 드릴 고기 한 근을 끊어 신문지에 싸 들고 집으로 갔다":"Số trên bảng lương nhích lên một chút, trên đường tan làm cắt một cân thịt cho {0}, gói trong tờ báo rồi xách về nhà",
"월급 명세서 숫자가 조금 늘어, 퇴근길에 늘 지나치던 가게에서 제일 큰 빵을 하나 사서 걸으며 뜯어 먹었다":"Số trên bảng lương nhích lên một chút, trên đường tan làm ghé tiệm hay đi ngang, mua ổ bánh mì to nhất và vừa đi vừa xé ăn",
"월급날 창구 줄에 서서 고향 식구에게 보낼 돈을 먼저 떼어 놓고, 남은 걸로 한 달을 짰다":"Ngày lĩnh lương xếp hàng ở quầy, để riêng tiền gửi về cho người nhà ở quê trước, rồi lo một tháng bằng phần còn lại",
"월급날마다 일부를 따로 옮겨 두는 습관이 작은 통장 안에 조금씩 쌓이기 시작했다":"Thói quen cứ mỗi kỳ lương lại chuyển riêng một phần ra bắt đầu dồn lại từng chút trong tài khoản nhỏ",
"월급날이 지나도 입금이 없어 사장에게 문자를 보냈고, 답은 이틀이 지나서야 짧게 한 줄 왔다":"Qua ngày lĩnh lương mà tiền vẫn chưa vào, nhắn tin cho ông chủ, hai ngày sau mới có một dòng trả lời ngắn",
"월급날이면 창구 줄에 서서 {0}에게 보낼 돈을 먼저 떼어 놓고, 남은 걸로 빠듯하게 한 달을 짰다":"Mỗi ngày lĩnh lương xếp hàng ở quầy, để riêng tiền gửi cho {0} trước, rồi dè sẻn lo một tháng bằng phần còn lại",
"월급만으로는 빠듯하다":"Chỉ mỗi tiền lương thì eo hẹp",
"월급에서 매달 일정액을 떼어 처음으로 투자 계좌를 열고, 숫자가 오르내리는 화면을 하루에 몇 번씩 들여다봤다":"Mỗi tháng trích một khoản cố định từ lương, lần đầu mở tài khoản đầu tư, một ngày nhìn mấy lần vào màn hình có con số lên xuống",
"월급을 지킨다":"Giữ lấy tiền lương",
"월급이 들어오면 통장에서 한꺼번에 빠져나가는 숫자부터 확인하는 버릇이 어느새 생겼다":"Lương vừa vào đã thành thói quen nhìn trước con số bị rút ra một lượt khỏi tài khoản lúc nào chẳng hay",
"월급이 오른 날, 장터 밥집에 들러 평소보다 한 그릇을 더 시켜 천천히 비웠다":"Hôm được tăng lương, ghé quán cơm ở chợ gọi nhiều hơn thường lệ một bát, từ từ ăn hết",
"월말이 되자 하루 두 끼를 한 끼로 줄이고, 물을 자주 마시며 허기를 누른 채 일터로 향했다":"Cuối tháng, giảm hai bữa mỗi ngày còn một bữa, uống nước liên tục để nén cơn đói rồi đi làm",
"월세를 들고 간 날 주인 할머니가 현관에서 귤 한 봉지를 내밀며, 밥은 제때 먹고 다니느냐고 물었다":"Hôm mang tiền nhà đến, bà chủ nhà ở cửa đưa một túi quýt, hỏi có ăn đúng bữa không",
"위층에서 밤새 쿵쿵거리는 발소리에 잠을 설치다 새벽이 되어서야 서랍 속 이어플러그를 찾아 귀에 꽂았다":"Mất ngủ vì tiếng chân thình thịch trên lầu cả đêm, đến sáng mới tìm thấy nút bịt tai trong ngăn kéo mà nhét vào",
"윗집 발소리 문제로 인터폰을 들었다가 말이 거칠어졌고, 그 뒤로 엘리베이터에서 마주쳐도 고개를 돌렸다":"Nhấc điện thoại nội bộ vì tiếng chân hàng xóm trên lầu rồi lời qua tiếng lại, từ đó gặp trong thang máy cũng quay mặt đi",
"유치하다는 말을 삼키고 구석에서 삽질하는 아이들을 구경했다":"Nuốt lại lời chê trẻ con, đứng nhìn bọn trẻ đào xới trong góc",
"유학 간다":"Đi du học",
"유학 때 기숙사에서 같이 지낸 친구가 짐 가방을 끌고 찾아와, 우리는 밤새 그때 얘기를 나눴다":"Người bạn từng ở chung ký túc xá thời du học kéo vali đến tìm, cả hai nói chuyện thời đó suốt đêm",
"유학 때 익힌 말로 낯선 방문객 옆에서 통역을 거들자, 굳어 있던 회의실 분위기가 눈에 띄게 풀렸다":"Dùng ngoại ngữ học được hồi du học phiên dịch hộ cho vị khách lạ, bầu không khí cứng đờ trong phòng họp dịu đi thấy rõ",
"유학을 보낸다":"Gửi đi du học",
"은행 문 앞에서 들고 간 서류를 반으로 접어 가방에 넣고 조용히 돌아섰다":"Trước cổng ngân hàng, gấp đôi xấp giấy tờ mang theo, bỏ vào cặp rồi lặng lẽ quay đi",
"은행에서 온 독촉장이 우편함에 쌓여 가고 나는 밤마다 식탁에서 계산기만 두드렸다":"Thư đòi nợ của ngân hàng chất đống trong hòm thư, đêm nào mình cũng ngồi bấm máy tính bên bàn ăn",
