"집 뒤편 헛간을 치워 내 방으로 쓰기로 하고, 낡은 이불을 깔고 첫날 밤 문고리를 두 번 확인했다":"Dọn cái kho sau nhà làm phòng của mình, trải tấm chăn cũ, đêm đầu tiên kiểm tra chốt cửa hai lần",
