"집에 화장실이 없어서 해가 지면 형제와 짝을 지어 손전등도 없이 어두운 풀숲까지 걸어 나갔다":"Nhà không có nhà vệ sinh nên trời tối thì cùng anh chị em ghép cặp đi bộ ra bụi cỏ tối om mà chẳng có đèn pin",
"집에서 모신다":"Chăm sóc tại nhà",
"집으로 모신다":"Đón về nhà ở",
