"참고 견딘다":"Nhẫn nhịn chịu đựng",
"참고 기다린다":"Nhẫn nại chờ đợi",
"참고 넘긴다":"Bỏ qua",
"창가에서 불어나는 물소리를 들었다. 아침에 보니 마을 길이 반쯤 잠겨 있었다":"Nghe tiếng nước dâng lên bên cửa sổ. Sáng ra thấy con đường làng ngập một nửa",
"창밖으로 처음 눈이 내리는 걸 보고 맨발로 문밖까지 뛰어나가 두 팔을 벌리고 소리를 질렀다":"Thấy ngoài cửa sổ tuyết rơi lần đầu, chân trần chạy ra tận ngoài cửa, dang hai tay hét lên",
"찾아 나선다":"Lên đường đi tìm",
"찾아가 만난다":"Tìm đến gặp",
"찾아가 얘기한다":"Tìm đến nói chuyện",
"채점된 시험지에 빨간 동그라미만 가득한 걸 보고 자리에서 벌떡 일어날 뻔했지만 옆자리 눈치에 손만 꽉 쥐었다":"Thấy bài thi đã chấm toàn dấu khoanh đỏ, suýt bật dậy khỏi chỗ ngồi nhưng bị người bên cạnh nhìn nên chỉ nắm chặt tay",
"책상 모서리만 보며 숨을 죽였다. 다른 아이가 걸려 가슴이 쓸어내려졌다":"Chỉ nhìn góc bàn, nín thở. Đứa khác bị bắt nên thở phào nhẹ nhõm",
