"책상 이름표가 한 단계 바뀐 날, 퇴근길 빵집에 들러 아무도 모르게 작은 케이크를 하나 샀다":"Hôm bảng tên trên bàn lên một bậc, trên đường tan làm ghé tiệm bánh, mua lén một chiếc bánh kem nhỏ mà không ai hay",
