"처마 밑에서 기다린다":"Đợi dưới mái hiên",
"처음 먹어 본 묽은 쌀미음을 혀로 몇 번 밀어내다가 결국 한 숟가락을 꿀꺽 삼켰다":"Dùng lưỡi đẩy ra mấy lần món cháo gạo loãng lần đầu ăn thử, cuối cùng nuốt ực được một thìa",
"처음 먹어 본 묽은 옥수수죽이 싱거운지 입을 오물거리며 한참 고개를 갸웃거렸다":"Nhóp nhép miệng, nghiêng đầu mãi vì món cháo ngô loãng lần đầu ăn thử nhạt quá",
"처음 먹어 본 으깬 감자를 손으로 헤집다가 얼굴 전체에 묻히고도 신이 나서 웃었다":"Quơ tay vào món khoai tây nghiền lần đầu ăn thử, dính đầy mặt mà vẫn cười hớn hở",
"처음 한 아르바이트 첫 월급봉투를 두 손으로 받아 한참 두께를 가늠하다 차마 뜯지 못하고 주머니에 넣었다":"Hai tay nhận phong bì lương đầu tiên của công việc làm thêm đầu tiên, nhấc nhấc đoán độ dày hồi lâu rồi chẳng nỡ bóc, nhét vào túi",
"처음으로 동전 몇 닢이 내 몫으로 생겼다":"Lần đầu tiên có vài đồng xu thuộc về mình",
"처음으로 용돈을 내 손으로 받았다":"Lần đầu tự tay nhận tiền tiêu vặt",
