"천변을 청소한다":"Dọn dẹp bờ suối",
"천장에서 비가 새는 자리에 양동이를 놓다가, 이웃에게 사다리를 빌려 직접 올라가 방수 천을 덧댔다":"Đang đặt xô chỗ trần dột thì mượn thang của hàng xóm, tự trèo lên vá thêm tấm vải chống thấm",
"첫 데이트 때 듣던 노래가 나오자 {0}의 이름을 속으로 부르며 눈을 감았다":"Khi bài hát nghe hồi hẹn hò lần đầu vang lên, nhắm mắt thầm gọi tên {0}",
"첫 발표에서 말씨가 튀어 웃음이 터졌지만 끝까지 내 말로 마쳤다. 박수는 그 뒤에 더 컸다":"Lần đầu thuyết trình bật ra giọng địa phương làm mọi người bật cười, nhưng vẫn kết thúc bằng lời của mình. Sau đó tràng pháo tay còn lớn hơn",
"첫 월급 봉투를 뜯지도 않고 {0}의 손에 쥐여 드렸고, 둘이 시장 국숫집에서 국수 한 그릇씩을 비웠다":"Chưa kịp bóc phong bì lương đầu tiên đã nhét vào tay {0}, hai người ăn mỗi người một bát mì ở quán mì trong chợ",
"첫 월급날, 일터 문 앞에서 {0}의 작업복 뒤를 졸졸 따르던 어린 나의 발소리가 불쑥 들렸다":"Ngày nhận lương đầu tiên, trước cửa chỗ làm, bỗng nghe tiếng bước chân bé xíu của mình thuở nhỏ lẽo đẽo theo sau áo bảo hộ của {0}",
"첫 월급을 받은 날, 한참 고르다 제일 싼 식당에서 제일 비싼 메뉴를 시켜 먹었다":"Ngày nhận lương đầu tiên, chọn mãi rồi gọi món đắt nhất ở quán rẻ nhất mà ăn",
"첫 일터에서 받은 거친 장갑이 아직 서랍에 있어, 손가락을 끼워 보고 웃었다":"Đôi găng thô nhận ở chỗ làm đầu tiên vẫn còn trong ngăn kéo, xỏ ngón tay vào thử rồi mỉm cười",
"첫 줄에서 말이 막혀 얼굴이 빨개졌다. 박수는 그래도 따뜻했다":"Vấp ở dòng đầu, mặt đỏ bừng. Tràng pháo tay vẫn ấm áp",
"첫 직장 사원증이 서랍에서 나와, 사진 속 앳된 얼굴을 한참 들여다보았다":"Thẻ nhân viên của công ty đầu tiên lòi ra trong ngăn kéo, nhìn mãi gương mặt non nớt trong ảnh",
"첫 직장이 나와 안 맞는다":"Công việc đầu tiên không hợp với mình",
