"초등학교를 마쳤다":"Đã học xong tiểu học",
"추수철 온 마을이 한 밭에서 번갈아 일했고, 곡식 쌓인 마당에서 따뜻한 국이 돌았다":"Mùa gặt cả làng thay phiên nhau làm trên một thửa ruộng, bát canh nóng chuyền quanh sân chất đầy lúa",
"추수철에 {0}와/과 해 뜨기 전부터 낫을 들고 나가, 저녁엔 곡식단 위에 나란히 앉아 찬 물을 나눠 마셨다":"Mùa gặt cùng {0} cầm liềm ra ruộng từ trước khi mặt trời mọc, chiều tối ngồi cạnh nhau trên bó lúa chia nhau nước lạnh uống",
"추운 겨울밤 {0}와/과 한 이불을 나눠 덮고 시린 발을 서로 맞대고 킥킥대다 잠들었다":"Đêm đông lạnh cùng {0} đắp chung chăn, chân buốt áp vào nhau khúc khích cười rồi ngủ thiếp",
"축구":"Bóng đá",
"축제 날 우리 반 부스에서 번 돈으로 마지막에 모두 함께 간식 가게에 몰려가 튀김 한 판을 나눠 먹으며 웃었다":"Ngày hội, dùng tiền lời từ quầy hàng của lớp, cuối cùng cả bọn kéo nhau vào tiệm đồ ăn vặt, chia nhau một đĩa đồ chiên mà cười",
"축제 저녁 광장에서 사람들 틈에 끼어 처음 보는 춤을 어설프게 따라 추다 옆 사람과 부딪혀 같이 웃었다":"Tối ngày hội chen vào đám đông ở quảng trường, vụng về múa theo điệu lần đầu thấy, va phải người bên cạnh rồi cùng bật cười",
"축제 저녁 집집마다 등불이 켜진 골목을 사촌들과 뛰어다니며 하늘로 오르는 불꽃을 구경했다":"Tối ngày hội, cùng các anh chị em họ chạy trong con hẻm nhà nào cũng thắp đèn lồng, ngắm pháo hoa bay lên trời",
"출근 버스가 이십 분째 오지 않아 정류장 벽에 기댄 채, 오늘 하루를 미리 지친 몸으로 시작했다":"Chuyến xe buýt đi làm hai mươi phút vẫn chưa tới, dựa vào tường trạm chờ, bắt đầu một ngày đã mệt từ trước",
"출근 전철에서 사람 틈에 끼여 두 정거장을 발이 뜬 채 갔고, 내리고 보니 구두 한 짝이 헐렁했다":"Trên chuyến tàu đi làm bị kẹp giữa đám đông, đi hai trạm mà chân không chạm đất, xuống rồi mới thấy một chiếc giày lỏng ra",
"출산 중 합병증":"Biến chứng khi sinh",
